{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="Practical, habit-focused coaching to help busy people feel clearer, calmer, and more consistent." />
  <link rel="stylesheet" href="assets/css/styles.css" />
</head>
<body class="site-root">
  <header class="nav">
    <div class="nav-inner">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="nav-links" id="navLinks">
        <a href="/">Home</a>
        <a href="about.html">About</a>
        <a href="programs.html">Paths</a>
        <a href="pricing.html">Pricing</a>
        <a href="testimonials.html">Praise</a>
        <a href="book.html" class="cta-small">Book</a>
      </nav>
      <button class="nav-toggle" id="navToggle" aria-label="Toggle navigation">☰</button>
    </div>
  </header>

  <main>
    <!-- HERO (gallery-style) -->
    <section class="hero" id="hero">
      <div class="hero-grid">
        <div class="hero-media">
          <img src="assets/img/hero.svg" alt="illustration" class="hero-svg" />
        </div>
        <div class="hero-content">
          <h1 class="hero-title">{{BUSINESS_NAME}} — {{TAGLINE}}</h1>
          <p class="hero-sub">Small, sustainable shifts that add up. Practical routines, accountability, and a clear map to your next 90 days.</p>
          <div class="hero-ctas">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn ghost" href="book.html">Schedule a free consult</a>
          </div>
          <p class="hero-meta">Call or text <strong>{{PHONE}}</strong> • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
        </div>
      </div>
    </section>

    <!-- STORY -->
    <section class="story" id="story">
      <div class="container">
        <div class="story-inner">
          <div class="story-avatar">
            <img src="assets/img/avatar.svg" alt="{{COACH_NAME}} avatar" />
          </div>
          <div class="story-copy">
            <h2>Meet {{COACH_NAME}}, {{CREDENTIALS}}</h2>
            <p>I blend evidence-informed habit design with the practical support people need to actually change. Based in {{CITY}}, {{STATE}}, I work with professionals who want momentum, not motivation — a friendly partner who helps you build habits into a busy life.</p>
            <p class="muted">You’ll get a compact playbook, weekly check-ins, and tools that fit your day — not your idealized schedule.</p>
            <a class="btn" href="about.html">Learn the full story</a>
          </div>
        </div>
      </div>
    </section>

    <!-- FRAMEWORK -->
    <section class="framework" id="framework">
      <div class="container">
        <h3 class="section-lead">My Simple Framework</h3>
        <h2 class="section-title">Understand • Design • Practice • Maintain</h2>
        <p class="section-sub">A gallery of intentional moves: we diagnose current patterns, design tiny tests, build routines, and tune systems so results stick.</p>
        <div class="cards grid-4">
          <div class="card">
            <div class="card-visual">1</div>
            <h4>Understand</h4>
            <p>Spot the moments that matter, identify friction, and choose what to change first.</p>
          </div>
          <div class="card">
            <div class="card-visual">2</div>
            <h4>Design</h4>
            <p>Create micro-habits and environment nudges you can actually do in your day.</p>
          </div>
          <div class="card">
            <div class="card-visual">3</div>
            <h4>Practice</h4>
            <p>Short accountability cycles and gentle habit rituals until they become automatic.</p>
          </div>
          <div class="card">
            <div class="card-visual">4</div>
            <h4>Maintain</h4>
            <p>Routines evolve — we build checkpoints, recovery plans, and seasonal tuning so gains last.</p>
          </div>
        </div>
      </div>
    </section>

    <!-- PROGRAMS (gallery showcase) -->
    <section class="programs" id="programs">
      <div class="container">
        <h3 class="section-lead">Coaching Paths</h3>
        <h2 class="section-title">Ways to Work Together</h2>
        <p class="section-sub">Hybrid options: remote check-ins plus optional in-person strategy days for local clients.</p>
        <div class="program-grid">
          <article class="program-card">
            <h4>Spark Plan — 8 weeks</h4>
            <p class="muted">Quick habit launches to get momentum and early wins.</p>
            <ul>
              <li>Weekly 30-min coaching</li>
              <li>Custom micro-habit playbook</li>
              <li>Email support</li>
            </ul>
            <a class="btn" href="programs.html">Explore Spark</a>
          </article>

          <article class="program-card featured">
            <h4>Habit Flow — 12 weeks</h4>
            <p class="muted">A full habit architecture: design + practice + systems.</p>
            <ul>
              <li>Weekly 50-min calls</li>
              <li>Quarterly roadmap + tracking</li>
              <li>Private messaging & check-ins</li>
            </ul>
            <a class="btn" href="programs.html">See Habit Flow</a>
          </article>

          <article class="program-card">
            <h4>Sustained Thrive — 6 months</h4>
            <p class="muted">Long-term partnership with seasonal planning and reset sessions.</p>
            <ul>
              <li>Bi-weekly coaching</li>
              <li>In-person strategy day (local)</li>
              <li>Annual maintenance plan</li>
            </ul>
            <a class="btn" href="programs.html">Start Thrive</a>
          </article>
        </div>
      </div>
    </section>

    <!-- PRICING (framing as investment tiers) -->
    <section class="pricing" id="pricing">
      <div class="container">
        <h3 class="section-lead">Investment</h3>
        <h2 class="section-title">Simple pricing, clear value</h2>
        <p class="section-sub">Choose a pathway that fits your schedule and goals. All packages include a start-up planning session.</p>
        <div class="pricing-grid">
          <div class="price-card">
            <h4>Launch — 8 weeks</h4>
            <div class="price-amount">$699</div>
            <p>Fast start for a single focus area.</p>
            <a class="btn" href="pricing.html">Choose Launch</a>
          </div>
          <div class="price-card recommended">
            <h4>Momentum — 12 weeks</h4>
            <div class="price-amount">$1,499</div>
            <p>Best for building multiple habits that stick.</p>
            <a class="btn" href="pricing.html">Choose Momentum</a>
          </div>
          <div class="price-card">
            <h4>Steady — 6 months</h4>
            <div class="price-amount">$3,900</div>
            <p>Long-term coaching with seasonal tuning.</p>
            <a class="btn" href="pricing.html">Choose Steady</a>
          </div>
        </div>
      </div>
    </section>

    <!-- TESTIMONIALS -->
    <section class="testimonials" id="testimonials">
      <div class="container">
        <h3 class="section-lead">Client Wins</h3>
        <h2 class="section-title">Stories of consistent change</h2>
        <div class="test-slider" id="testSlider">
          <blockquote class="quote active">"Working with {{COACH_NAME}} helped me swap one small habit that unlocked energy every morning. Simple and sustainable."<cite>— Alex, Product Manager</cite></blockquote>
          <blockquote class="quote">"The Habit Flow plan gave me a clear roadmap and the accountability I needed to follow through."<cite>— Priya, Designer</cite></blockquote>
          <blockquote class="quote">"I finally learned how to design my day so movement and focus happen without willpower."<cite>— Marcus, Lawyer</cite></blockquote>
        </div>
        <div class="test-controls">
          <button id="prev">◀</button>
          <button id="next">▶</button>
        </div>
        <p class="leadmag">Free guide: "90 Days to a Habit You Keep" — available when you schedule a consult.</p>
      </div>
    </section>

    <!-- FINAL CTA -->
    <section class="final-cta" id="finalCta">
      <div class="container cta-inner">
        <div>
          <h2>Ready to build momentum?</h2>
          <p>Book a complimentary conversation and get a short, actionable habit plan to try this week.</p>
        </div>
        <div class="cta-actions">
          <a class="btn primary large" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn ghost" href="contact.html">Contact: {{EMAIL}}</a>
        </div>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="container footer-inner">
      <div class="footer-left">© <span id="year"></span> {{BUSINESS_NAME}} • <a href="privacy.html">Privacy</a></div>
      <div class="footer-right">Call <a href="tel:{{PHONE}}">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
    </div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
