{"path":"assets/css/styles.css","content":"/* Lux Gallery — styles.css */
:root{--bg:#fff;--muted:#6b6b73;--accent:#7b3cff;--accent-2:#00bfa6;--card:#f7f7fb;--max:1100px}
*{box-sizing:border-box}
body{font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial;line-height:1.45;color:#111;background:var(--bg);margin:0}
.container{max-width:var(--max);margin:0 auto;padding:48px 20px}
.nav{border-bottom:1px solid #eee;background:rgba(255,255,255,0.9);backdrop-filter:blur(4px)}
.nav-inner{max-width:var(--max);margin:0 auto;display:flex;align-items:center;justify-content:space-between;padding:18px 20px}
.brand{font-weight:700;color:#111;text-decoration:none}
.nav-links{display:flex;gap:18px;align-items:center}
.nav-links a{color:#333;text-decoration:none;font-weight:500}
.cta-small{padding:8px 12px;background:var(--accent);color:#fff;border-radius:8px}
.nav-toggle{display:none;background:none;border:0;font-size:20px}

/* Hero gallery */
.hero{padding:48px 0;background:linear-gradient(180deg,#fff,#fbfbff)}
.hero-grid{display:grid;grid-template-columns:1fr 520px;gap:40px;align-items:center;max-width:1200px;margin:0 auto}
.hero-media{display:flex;justify-content:center}
.hero-svg{width:100%;max-width:600px}
.hero-title{font-size:32px;margin:0 0 12px;color:#0d0d12}
.hero-sub{color:var(--muted);margin:0 0 18px}
.hero-ctas .btn{margin-right:12px}
.hero-meta{margin-top:12px;color:var(--muted);font-size:14px}

/* Story */
.story{background:linear-gradient(90deg,#fff,#fcfbff);padding:36px 0}
.story-inner{display:flex;gap:28px;align-items:center}
.story-avatar img{width:160px;border-radius:12px;background:var(--card);padding:18px}
.story-copy h2{margin:0 0 8px}
.muted{color:var(--muted)}

/* Framework */
.framework{padding:36px 0}
.section-lead{color:var(--accent-2);font-weight:600;margin-bottom:6px}
.section-title{margin:0 0 12px}
.cards{margin-top:18px}
.grid-4{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}
.card{background:var(--card);padding:20px;border-radius:12px}
.card-visual{width:44px;height:44px;border-radius:8px;background:linear-gradient(135deg,var(--accent),var(--accent-2));color:#fff;display:flex;align-items:center;justify-content:center;font-weight:700;margin-bottom:12px}

/* Programs */
.programs{padding:36px 0}
.program-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.program-card{background:#fff;border:1px solid #eee;padding:22px;border-radius:12px}
.program-card.featured{box-shadow:0 6px 24px rgba(123,60,255,0.08);border-color:rgba(123,60,255,0.12)}

/* Pricing */
.pricing{padding:36px 0}
.pricing-grid{display:flex;gap:18px}
.price-card{flex:1;background:var(--card);padding:20px;border-radius:12px;text-align:center}
.price-card.recommended{transform:translateY(-6px);border:2px solid var(--accent)}
.price-amount{font-size:22px;font-weight:700;margin:8px 0}

/* Testimonials */
.testimonials{padding:36px 0;background:#fbfbff}
.test-slider{position:relative;min-height:120px}
.quote{display:none;padding:18px 24px;border-left:4px solid var(--accent);background:#fff;border-radius:8px}
.quote.active{display:block}
.quote cite{display:block;margin-top:10px;color:var(--muted);font-size:14px}
.test-controls{margin-top:12px}
.test-controls button{background:#fff;border:1px solid #eee;padding:8px 12px;border-radius:8px;margin-right:6px}
.leadmag{margin-top:12px;color:var(--muted)}

/* CTA */
.final-cta{padding:36px 0;border-top:1px dashed #eee}
.cta-inner{display:flex;align-items:center;justify-content:space-between;gap:20px}
.cta-actions{display:flex;gap:12px}
.btn{display:inline-block;padding:10px 16px;border-radius:10px;text-decoration:none;color:#111;border:1px solid transparent;font-weight:600}
.btn.primary{background:var(--accent);color:#fff}
.btn.ghost{background:transparent;border-color:#ddd}
.btn.large{padding:14px 20px;font-size:16px}

/* Footer */
.site-footer{border-top:1px solid #eee;padding:20px 0;margin-top:40px}
.footer-inner{max-width:var(--max);margin:0 auto;display:flex;justify-content:space-between;padding:0 20px;color:var(--muted)}

/* Responsive */
@media (max-width:980px){
  .hero-grid{grid-template-columns:1fr;gap:28px}
  .grid-4{grid-template-columns:repeat(2,1fr)}
  .program-grid{grid-template-columns:1fr}
  .pricing-grid{flex-direction:column}
  .nav-links{display:none}
  .nav-toggle{display:block}
}
@media (max-width:560px){
  .grid-4{grid-template-columns:1fr}
  .cta-inner{flex-direction:column;align-items:flex-start}
}
"} 
{"path":"assets/js/main.js","content":"// Main interactivity: nav toggle, smooth scroll, testimonial slider
(function(){
  var navToggle = document.getElementById('navToggle');
  var navLinks = document.getElementById('navLinks');
  var yearEl = document.getElementById('year');
  var prev = document.getElementById('prev');
  var next = document.getElementById('next');
  var slides = document.querySelectorAll('.quote');
  var current = 0;

  if(yearEl) yearEl.textContent = new Date().getFullYear();

  if(navToggle && navLinks){
    navToggle.addEventListener('click', function(){
      var open = navLinks.style.display === 'flex';
      navLinks.style.display = open ? '' : 'flex';
      navLinks.style.flexDirection = open ? '' : 'column';
    });
  }

  function showSlide(idx){
    slides.forEach(function(s,i){
      s.classList.toggle('active', i===idx);
    });
  }
  function nextSlide(){ current = (current+1) % slides.length; showSlide(current); }
  function prevSlide(){ current = (current-1+slides.length) % slides.length; showSlide(current); }

  if(next) next.addEventListener('click', nextSlide);
  if(prev) prev.addEventListener('click', prevSlide);

  // Auto rotate testimonials gently
  setInterval(nextSlide, 6000);

  // Smooth anchors
  document.querySelectorAll('a[href^="#"]').forEach(function(a){
    a.addEventListener('click', function(e){
      e.preventDefault();
      var target = document.querySelector(this.getAttribute('href'));
      if(target) target.scrollIntoView({behavior:'smooth',block:'start'});
    });
  });
})();
"} 
